ocess(); // call a function that might generate a disk-related exception\n  } catch (FloppyDiskException $fde) {\n    echo \"In handler for FloppyDiskException\\n\";\n    // ...\n  } catch (RemovableDiskException $rde) {\n    echo \"In handler for RemovableDiskException\\n\";\n    // ...\n  } catch (DiskException $de) {\n    echo \"In handler for DiskException\\n\";\n    // ...\n  } catch (DeviceException $dve) {\n    echo \"In handler for DeviceException\\n\";\n    // ...\n  } finally {\n    echo \"In finally block\\n\";\n    // perform some cleanup\n  }\n}\n"}, {"lang": "hack", "shikiLang": "hack", "name": "facebook__hhvm__hphp_hack_test_extracted_from_manual_15-asyn", "code": "// @generated by hh_manual from manual/hack/15-asynchronous-operations/28-guidelines.md\n// @codegen-command : buck run fbcode//hphp/hack/src/hh_manual:hh_manual extract fbcode/hphp/hack/manual/hack/\nclass User {\n  public string $name;\n\n  protected function __construct(string $name) {\n    $this->name = $name;\n  }\n\n  public static function get_name(int $id): User {\n    return new User(\\str_shuffle(\"ABCDEFGHIJ\").\\strval($id));\n  }\n}\n\nasync function load_user(int $id): Awaitable<User> {\n  // Load user from somewhere (e.g., database).\n  // Fake it for now\n  return User::get_name($id);\n}\n\nasync function load_users_await_loop(vec<int> $ids): Awaitable<vec<User>> {\n  $result = vec[];\n  foreach ($ids as $id) {\n    $result[] = await load_user($id);\n  }\n  return $result;\n}\n\n<<__EntryPoint>>\nasync function runMe(): Awaitable<void> {\n  $ids = vec[1, 2, 5, 99, 332];\n  $result = await load_users_await_loop($ids);\n  \\var_dump($result[4]->name);\n}\n"}, {"lang": "hack", "shikiLang": "hack", "name": "facebook__hhvm__hphp_hack_test_extracted_from_manual_06-clas", "code": "// @generated by hh_manual from manual/hack/06-classes/31-type-constants-revisited.md\n// @codegen-command : buck run fbcode//hphp/hack/src/hh_manual:hh_manual extract fbcode/hphp/hack/manual/hack/\nabstr